import{_ as e,c as t,o,V as r}from"./chunks/framework.GYYi-SO7.js";const b=JSON.parse('{"title":"Research overview","description":"","frontmatter":{},"headers":[],"relativePath":"research/introduction.md","filePath":"research/introduction.md"}'),a={name:"research/introduction.md"},d=r('<h1 id="research-overview" tabindex="-1">Research overview <a class="header-anchor" href="#research-overview" aria-label="Permalink to &quot;Research overview&quot;">​</a></h1><p>This section documents the research phase of knowledge — the exploration that produced the design decisions now used in production. The work was carried out as six Jupyter notebooks (<code>nb01</code>–<code>nb06</code>); each page walks through one notebook: the question it asked, what was tried, and what it concluded.</p><h2 id="how-the-experiments-were-evaluated" tabindex="-1">How the experiments were evaluated <a class="header-anchor" href="#how-the-experiments-were-evaluated" aria-label="Permalink to &quot;How the experiments were evaluated&quot;">​</a></h2><p>A shared, deterministic method runs across the notebooks so results are comparable:</p><ul><li><strong>Gold query sets</strong> — curated question→expected-source pairs, including a 200-question bilingual (FR / EN) set, used to score retrieval objectively.</li><li><strong>Deterministic retrieval metrics</strong> — <code>recall@k</code>, source coverage and related measures, shared across <code>nb02</code>–<code>nb06</code> (not eyeballed).</li><li><strong>Token tracking</strong> — bundle/context token counts, to compare strategies on cost as well as accuracy.</li></ul><h2 id="the-six-notebooks" tabindex="-1">The six notebooks <a class="header-anchor" href="#the-six-notebooks" aria-label="Permalink to &quot;The six notebooks&quot;">​</a></h2><table><thead><tr><th>#</th><th>Topic</th><th>Outcome</th><th>Status</th></tr></thead><tbody><tr><td><a href="/knowledge/research/corpus-discovery.html">nb01</a></td><td>Corpus discovery &amp; filtering</td><td>Profile-driven file selection for the corpus</td><td>done</td></tr><tr><td><a href="/knowledge/research/markdown-chunking.html">nb02</a></td><td>Markdown chunking</td><td>Selected: AST-merge + breadcrumb, <code>chunk_size=500</code></td><td>done</td></tr><tr><td><a href="/knowledge/research/js-vue-chunking.html">nb03</a></td><td>JS &amp; Vue SFC chunking</td><td>Structure-aware chunkers + BM25/RRF hybrid retrieval</td><td>done</td></tr><tr><td><a href="/knowledge/research/json-chunking.html">nb04</a></td><td>JSON chunking</td><td>Category-aware key splitting</td><td>done</td></tr><tr><td><a href="/knowledge/research/embedding-evaluation.html">nb05</a></td><td>Embedding model evaluation</td><td>Recommends <code>Qwen3-Embedding-0.6B</code></td><td>done</td></tr><tr><td><a href="/knowledge/research/qdrant-index-eval.html">nb06</a></td><td>Qdrant index &amp; evaluation</td><td>Real Qdrant index, verified against nb05; Qdrant / Chroma / LanceDB comparison</td><td>done</td></tr></tbody></table><h2 id="how-the-findings-feed-production" tabindex="-1">How the findings feed production <a class="header-anchor" href="#how-the-findings-feed-production" aria-label="Permalink to &quot;How the findings feed production&quot;">​</a></h2><ul><li>Chunking winners (nb02–nb04) → the <a href="/knowledge/architecture/ingestion-pipeline.html">ingestion pipeline</a>.</li><li>Embedding choice (nb05) → <a href="/knowledge/architecture/rag.html">RAG: indexing &amp; retrieval</a>.</li><li>Index &amp; retrieval validation (nb06) → <a href="/knowledge/architecture/rag.html">RAG: indexing &amp; retrieval</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Notebooks &amp; code</p><p>The notebooks and their helper code live in the repository under <code>docs/experiments/</code> (<code>notebooks/nb0X_*.ipynb</code> plus the matching <code>*_lab/</code> helpers). They are <strong>not</strong> part of the rendered site — these pages are the readable write-up of what they contain.</p></div>',10),n=[d];function i(s,c,h,l,u,p){return o(),t("div",null,n)}const g=e(a,[["render",i]]);export{b as __pageData,g as default};
